create extension if not exists pgcrypto;
do $$begin create type public.user_role as enum('operator','underwriter','admin','auditor');exception when duplicate_object then null;end$$;
do $$begin create type public.referral_status as enum('received','processing','approved','manual_review','rejected','failed');exception when duplicate_object then null;end$$;
do $$begin create type public.workflow_status as enum('intake_pending','resolving_vehicle','lookup_pending','comparison_pending','auto_approved','queued_for_review','completed','failed_retrying','failed_terminal');exception when duplicate_object then null;end$$;
do $$begin create type public.provider_status as enum('pending','succeeded','failed','timeout','rate_limited','unavailable');exception when duplicate_object then null;end$$;
do $$begin create type public.review_status as enum('queued','assigned','in_review','completed','escalated');exception when duplicate_object then null;end$$;
do $$begin create type public.decision_type as enum('auto_approved','manual_review','rejected','pending');exception when duplicate_object then null;end$$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role public.user_role not null default 'operator',is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.referral_cases(id uuid primary key default gen_random_uuid(),external_case_id text not null unique,source_system text not null default 'corehub',registration_number text,make_raw text,model_raw text,variant_raw text,fuel_type_raw text,cc_raw text,requested_idv numeric(12,2),metadata jsonb not null default '{}'::jsonb,referral_status public.referral_status not null default 'received',workflow_status public.workflow_status not null default 'intake_pending',received_at timestamptz not null default now(),processed_at timestamptz,idempotency_key text not null unique,correlation_id text not null unique default gen_random_uuid()::text,last_error_code text,last_error_message text,retry_count integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.vehicle_resolutions(id uuid primary key default gen_random_uuid(),case_id uuid not null unique references public.referral_cases(id) on delete cascade,normalized_make text,normalized_model text,normalized_variant text,normalized_fuel text,normalized_cc numeric(8,2),candidate_source text not null default 'deterministic',resolved_vehicle_key text,resolved_make text,resolved_model text,resolved_variant text,confidence_score numeric(5,2),match_strategy text,match_reason_codes jsonb not null default '[]'::jsonb,candidate_payload jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.idv_checks(id uuid primary key default gen_random_uuid(),case_id uuid not null unique references public.referral_cases(id) on delete cascade,vehicle_resolution_id uuid references public.vehicle_resolutions(id),provider text not null default 'obv',provider_request_id text,provider_status public.provider_status not null default 'pending',fetched_idv numeric(12,2),fetched_currency text not null default 'INR',fetched_at timestamptz,lookup_latency_ms integer,raw_response jsonb,raw_request jsonb,retry_count integer not null default 0,circuit_state text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.approval_decisions(id uuid primary key default gen_random_uuid(),case_id uuid not null unique references public.referral_cases(id) on delete cascade,idv_check_id uuid references public.idv_checks(id),decision public.decision_type not null default 'pending',decision_reason_code text,decision_reason_details jsonb not null default '{}'::jsonb,requested_idv numeric(12,2),fetched_idv numeric(12,2),absolute_delta numeric(12,2),percentage_delta numeric(10,6),tolerance_mode text,tolerance_value numeric(12,2),decided_by uuid references auth.users(id),decided_at timestamptz not null default now(),created_at timestamptz not null default now());
create table if not exists public.manual_reviews(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.referral_cases(id) on delete cascade,assigned_to uuid references auth.users(id),review_status public.review_status not null default 'queued',priority integer not null default 3 check(priority between 1 and 5),review_reason text not null,reviewer_decision public.decision_type,reviewer_notes text,reviewed_at timestamptz,sla_due_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.audit_events(id uuid primary key default gen_random_uuid(),case_id uuid references public.referral_cases(id) on delete set null,event_type text not null,actor_type text not null default 'system',actor_id uuid references auth.users(id),severity text not null default 'info',payload jsonb not null default '{}'::jsonb,correlation_id text,created_at timestamptz not null default now());
create table if not exists public.config_settings(id uuid primary key default gen_random_uuid(),setting_key text not null unique,setting_value jsonb not null,description text,is_active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create index if not exists idx_referral_status_received on public.referral_cases(referral_status,received_at desc);
create index if not exists idx_workflow_status_updated on public.referral_cases(workflow_status,updated_at desc);
create index if not exists idx_reviews_queue on public.manual_reviews(review_status,priority,created_at);
create index if not exists idx_audit_case_date on public.audit_events(case_id,created_at desc);
alter table public.profiles enable row level security;alter table public.referral_cases enable row level security;alter table public.vehicle_resolutions enable row level security;alter table public.idv_checks enable row level security;alter table public.approval_decisions enable row level security;alter table public.manual_reviews enable row level security;alter table public.audit_events enable row level security;alter table public.config_settings enable row level security;
insert into public.config_settings(setting_key,setting_value,description)values('idv_abs_tolerance','5000','Maximum absolute INR deviation allowed for automatic approval'),('idv_pct_tolerance','0.02','Maximum percentage deviation allowed for automatic approval'),('vehicle_match_min_confidence','85','Minimum vehicle resolution confidence required for automatic approval'),('obv_lookup_timeout_ms','4000','External valuation lookup timeout in milliseconds'),('obv_max_retries','2','Maximum transient lookup retries'),('manual_review_sla_hours','4','Default manual review SLA')on conflict(setting_key)do nothing;